/**
 * Renders every query definition as `graph/queries.cypher`, the file the README embeds.
 * Generated by `pnpm gen:queries`; a test fails when the committed file is stale.
 */
import { depth } from './cypher.js';
import { DEFAULT_DEPTH, registry } from './queries.js';

const SECTIONS: Record<string, string> = {
  Q: 'The query catalogue (docs/PLAN.md §5)',
  S: 'Schema and meta',
  W: 'World (Entity.state)',
  R: 'Recording runs, steps and actions',
  P: 'Undo plans and policies',
  V: 'Views for the UI and the agents',
};
const ORDER = ['Q', 'S', 'W', 'R', 'P', 'V'];

export function renderCatalogue(): string {
  const out: string[] = [
    '// GENERATED by `pnpm gen:queries` from packages/core/src/graph/queries.ts. Do not edit.',
    '// Every value is a $parameter. The only literal is the variable-length bound, clamped to',
    `// 1..10 in code (FalkorDB rejects a parameter there); it is shown here at the default, ${DEFAULT_DEPTH}.`,
    '',
  ];
  const byNumber = (id: string) => Number(id.slice(1));
  for (const prefix of ORDER) {
    const defs = registry
      .filter((d) => d.id.startsWith(prefix))
      .sort((a, b) => byNumber(a.id) - byNumber(b.id));
    if (defs.length === 0) continue;
    out.push(`// ${'='.repeat(94)}`, `// ${SECTIONS[prefix]}`, `// ${'='.repeat(94)}`, '');
    for (const d of defs) {
      out.push(`// ${d.id} · ${d.title} (${d.mode}${d.usesDepth ? ', depth-bounded' : ''})`);
      out.push(`// answers: ${d.answers}`);
      out.push(`${d.text(depth(DEFAULT_DEPTH)).trim()};`, '');
    }
  }
  return out.join('\n');
}

export const README_BEGIN = '<!-- BEGIN GENERATED: queries (pnpm gen:queries) -->';
export const README_END = '<!-- END GENERATED: queries -->';

/** The Q catalogue as collapsible Cypher blocks for the README, between the markers above. */
export function renderReadmeQueries(): string {
  const qs = registry
    .filter((d) => d.id.startsWith('Q'))
    .sort((a, b) => Number(a.id.slice(1)) - Number(b.id.slice(1)));
  const blocks = qs.map((d) =>
    [
      `<details><summary><b>${d.id}</b> · ${d.title}</summary>`,
      '',
      `*answers:* ${d.answers}`,
      '',
      '```cypher',
      d.text(depth(DEFAULT_DEPTH)).trim(),
      '```',
      '',
      '</details>',
    ].join('\n'),
  );
  return [README_BEGIN, '', ...blocks, '', README_END].join('\n');
}

/** Replace the generated block in a README text (the markers must already be there). */
export function spliceReadme(readme: string): string {
  const start = readme.indexOf(README_BEGIN);
  const end = readme.indexOf(README_END);
  if (start === -1 || end === -1)
    throw new Error('README is missing the generated-queries markers');
  return readme.slice(0, start) + renderReadmeQueries() + readme.slice(end + README_END.length);
}
